const allowed = ($env.ALLOWED_TELEGRAM_USER_IDS || '').split(',').map(v => v.trim()).filter(Boolean);
const callbackData = $json.callback_query?.data || '';
const feedbackParts = callbackData.startsWith('feedback:') ? callbackData.split(':') : [];
const isFeedback = feedbackParts.length >= 2;
const followupParts = callbackData.startsWith('followup:') ? callbackData.split(':') : [];
const isFollowup = followupParts.length === 3;
const message = $json.message || $json.callback_query?.message || {};
const from = $json.message?.from || $json.callback_query?.from || {};
const messageId = $json.callback_query?.message?.message_id || null;
const userMessageId = $json.message?.message_id || $json.callback_query?.message?.message_id || null;
const userId = String(from.id || '');
const rawText = message.text || callbackData || '';
const normalizedText = rawText.trim().toLowerCase().replace(/ё/g, 'е').replace(/[.!?,]+$/g, '');

const greetingText = '<b>TestRag — HR/Legal RAG-ассистент</b>\n\n' +
  'Отвечаю на вопросы по корпоративным документам: HR-политики, кадровые шаблоны, договоры, претензии, авиагрузовая логистика. ' +
  'Каждый ответ сопровождается ссылками на конкретные источники и оценкой уверенности.\n\n' +
  '<b>Попробуйте:</b>\n' +
  '• Что такое controlled zone?\n' +
  '• Какие документы нужны для отправки dangerous goods авиатранспортом?\n' +
  '• Какие основания для досрочного расторжения трудового договора?\n\n' +
  '<b>Команды:</b> /help — справка · /docs — что в корпусе · /history — мои запросы · /clear — про сохранение состояния';

const helpText = '<b>Что я умею</b>\n' +
  '• Отвечаю на вопросы по HR, кадровому делопроизводству, договорам, претензиям, авиагрузовой логистике (AWB/MAWB/HAWB, controlled zone, dangerous goods, GHA, ULD, cutoff).\n' +
  '• Каждый ответ опирается на конкретные документы корпуса со ссылкой на раздел.\n' +
  '• Уверенность ответа маркируется как 🟢 высокая, 🟡 средняя или 🟠 низкая.\n' +
  '• 👍/👎 под ответом — оценка, попадает в очередь ревью.\n' +
  '• 📎 — дозапрос подробностей по конкретному источнику.\n' +
  '• 🧑‍💼 — эскалация к HR/Legal (последние 5 запросов прилагаются).\n\n' +
  '<b>Примеры вопросов</b>\n' +
  '• Что такое controlled zone?\n' +
  '• Какие документы нужны для отправки dangerous goods авиатранспортом?\n' +
  '• Какие основания для досрочного расторжения трудового договора?\n' +
  '• Какой испытательный срок по ТК РФ?\n' +
  '• Как составить претензию контрагенту?\n\n' +
  '<b>Команды</b>\n' +
  '/help — эта справка\n' +
  '/docs — категории и состав корпуса\n' +
  '/history — последние 5 запросов\n' +
  '/clear — про сохранение состояния';

const clearText = '<b>Контекст не сохраняется</b> — каждый ответ автономен и не зависит от предыдущих сообщений. ' +
  'Если нужно сослаться на старый запрос — используйте /history.';

const REASON_KEYS = ['inaccurate', 'outdated', 'human'];
let eventType = isFeedback ? 'feedback' : (isFollowup ? 'followup_request' : 'question');
let text = rawText;
let rating = null;
let category = null;
let requestLogId = null;
let followupIdx = null;
if (isFeedback) {
  const verb = feedbackParts[1] || '';
  requestLogId = feedbackParts[2] || null;
  if (verb === 'good') {
    rating = 'good';
  } else if (verb === 'bad') {
    eventType = 'feedback_bad_clarify';
    rating = null;
  } else if (verb.startsWith('bad_')) {
    const reasonKey = verb.slice(4);
    if (REASON_KEYS.includes(reasonKey)) {
      rating = 'bad';
      category = reasonKey;
    } else {
      eventType = 'direct_reply';
      text = 'Неизвестная причина обратной связи.';
    }
  } else {
    eventType = 'direct_reply';
    text = 'Неизвестная команда обратной связи.';
  }
}
if (isFollowup) {
  const parsedIdx = parseInt(followupParts[1], 10);
  followupIdx = Number.isFinite(parsedIdx) && parsedIdx >= 0 ? parsedIdx : null;
  requestLogId = followupParts[2] || null;
  if (followupIdx === null || !requestLogId) {
    eventType = 'direct_reply';
    text = 'Не удалось распознать запрос на уточнение. Задайте вопрос текстом.';
  }
}
if (!isFeedback && !isFollowup && !normalizedText) {
  eventType = 'direct_reply';
  text = 'Пока понимаю только текстовые вопросы. Задайте вопрос по HR, юридическим или договорным документам одним сообщением.';
}
if (!isFeedback && !isFollowup && ['привет', 'здравствуйте', 'добрый день', 'доброе утро', 'добрый вечер', 'hello', 'hi', '/start', 'start'].includes(normalizedText)) {
  eventType = 'direct_reply';
  text = greetingText;
}
if (!isFeedback && !isFollowup && ['спасибо', 'благодарю'].includes(normalizedText)) {
  eventType = 'direct_reply';
  text = 'Пожалуйста. Если нужен разбор по HR/legal-документам, задайте вопрос одним сообщением.';
}
if (!isFeedback && !isFollowup && (normalizedText === '/help' || normalizedText === 'help')) {
  eventType = 'direct_reply';
  text = helpText;
}
if (!isFeedback && !isFollowup && (normalizedText === '/clear' || normalizedText === 'clear')) {
  eventType = 'direct_reply';
  text = clearText;
}
if (!isFeedback && !isFollowup && (normalizedText === '/history' || normalizedText === 'history')) {
  eventType = 'history_request';
  text = '/history';
}
if (!isFeedback && !isFollowup && (normalizedText === '/docs' || normalizedText === 'docs')) {
  eventType = 'docs_request';
  text = '/docs';
}
if (!allowed.length) {
  return [{ json: { authorized: false, chat_id: message.chat?.id, user_id: userId, text: `Whitelist не настроен. Ваш Telegram ID: ${userId}. Добавьте его в ALLOWED_TELEGRAM_USER_IDS в локальном .env и перезапустите n8n.` } }];
}
if (!allowed.includes(userId)) {
  return [{ json: { authorized: false, chat_id: message.chat?.id, user_id: userId, text: `Доступ запрещен. Ваш Telegram ID: ${userId}.` } }];
}
return [{ json: { authorized: true, user_message_id: userMessageId, event_type: eventType, chat_id: message.chat?.id, message_id: messageId, user_id: userId, text, rating, category, request_log_id: requestLogId, followup_idx: followupIdx } }];

const escapeHtml = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pluralRu = (n) => {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return ['Последний', 'запрос'];
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return ['Последние', 'запроса'];
  return ['Последние', 'запросов'];
};
const items = ($json.items || []);
if (!items.length) {
  return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text: 'История запросов пуста. Задайте первый вопрос — он попадёт в /history.' } }];
}
const lines = items.map((it, i) => {
  const q = escapeHtml(it.question || '').slice(0, 120);
  const when = (it.created_at || '').slice(0, 16).replace('T', ' ');
  const tag = it.refused ? ' [отказ]' : '';
  return `${i + 1}. <b>${when}</b>${tag}\n   <code>${q}</code>`;
}).join('\n\n');
const [prefix, noun] = pluralRu(items.length);
const text = `<b>${prefix} ${items.length} ${noun}:</b>\n\n${lines}`;
return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text } }];

const escapeHtml = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cats = ($json.categories || []);
const total = $json.total_docs || 0;
if (!cats.length) {
  return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text: 'Корпус пуст или не загружен.' } }];
}
const lines = cats.map(c => {
  const samples = (c.sample_files || []).slice(0, 2).map(f => `<code>${escapeHtml(f)}</code>`).join(', ');
  const tail = samples ? ` — например ${samples}` : '';
  return `• <b>${escapeHtml(c.label)}</b> (${c.doc_count})${tail}`;
}).join('\n');
const text = `<b>Корпус знаний: ${total} документов</b>\n\n${lines}\n\n<i>Задайте вопрос по любой категории — ассистент найдёт релевантные документы и сошлётся на конкретные разделы.</i>`;
return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text } }];

const TG_MAX = 4000;

const escapeHtml = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mdToHtml = (s) => {
  s = s.replace(/`([^`\n]+)`/g, '<code>$1</code>');
  s = s.replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>');
  s = s.replace(/^- /gm, '• ');
  s = s.replace(/^\* /gm, '• ');
  return s;
};
const balanceTags = (s) => {
  ['b', 'code', 'i'].forEach(tag => {
    const opens = (s.match(new RegExp(`<${tag}>`, 'g')) || []).length;
    const closes = (s.match(new RegExp(`</${tag}>`, 'g')) || []).length;
    if (opens > closes) s = s + `</${tag}>`.repeat(opens - closes);
    if (closes > opens) s = `<${tag}>`.repeat(closes - opens) + s;
  });
  return s;
};

const confidenceChip = (conf) => {
  if (conf == null) return '';
  if (conf >= 0.7) return '🟢 <b>Высокая уверенность</b>';
  if (conf >= 0.4) return '🟡 <b>Средняя уверенность</b> — сверьтесь с источником';
  if (conf > 0) return '🟠 <b>Низкая уверенность</b> — рассмотрите 🧑‍💼 эскалацию';
  return '';
};

const REFUSAL_PATTERNS = [
  /данных недостаточно/i,
  /не нашел? в (предоставленных |)источниках/i,
  /не содерж[аи]т (информации|ответа)/i,
  /отсутствует определение/i,
  /в (корпусе|базе знаний) нет/i,
  /не нашел подходящих/i,
];
const looksRefusal = (s) => REFUSAL_PATTERNS.some(re => re.test(s));

const splitIntoParts = (full, max) => {
  if (full.length <= max) return [full];
  const parts = [];
  const paragraphs = full.split('\n\n');
  let current = '';
  const flush = () => { if (current) { parts.push(current); current = ''; } };
  for (const para of paragraphs) {
    const candidate = current ? current + '\n\n' + para : para;
    if (candidate.length <= max) { current = candidate; continue; }
    flush();
    if (para.length <= max) { current = para; continue; }
    const sentences = para.split(/(?<=[.!?])\s+/);
    let sCur = '';
    for (const s of sentences) {
      const sCand = sCur ? sCur + ' ' + s : s;
      if (sCand.length <= max) { sCur = sCand; continue; }
      if (sCur) { parts.push(sCur); sCur = ''; }
      if (s.length > max) {
        for (let i = 0; i < s.length; i += max) parts.push(s.slice(i, i + max));
      } else {
        sCur = s;
      }
    }
    if (sCur) parts.push(sCur);
  }
  flush();
  return parts.map(balanceTags);
};

const truncate = (s, max) => {
  const str = String(s == null ? '' : s);
  return str.length <= max ? str : str.slice(0, max - 1) + '…';
};

const seenFiles = new Set();
const dedupedSources = [];
const originalSources = $json.sources || [];
originalSources.forEach((s, originalIdx) => {
  const file = s.file || s.chunk_id || '';
  if (file && seenFiles.has(file)) return;
  seenFiles.add(file);
  dedupedSources.push({ ...s, _originalIdx: originalIdx });
});
const sourcesBlock = dedupedSources.map((s, i) => {
  const file = escapeHtml(s.file || s.chunk_id || 'unknown');
  const section = escapeHtml(s.section || 'раздел не указан');
  return `${i + 1}. <code>${file}</code> — ${section}`;
}).join('\n');

const count = dedupedSources.length;
const pluralRu = (n) => {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return 'релевантный документ';
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 'релевантных документа';
  return 'релевантных документов';
};

const rawAnswer = $json.answer || '';
const isRefusal = $json.refused === true || looksRefusal(rawAnswer);
const conf = $json.confidence;
const chip = isRefusal ? '' : confidenceChip(conf);

const answerHtml = mdToHtml(escapeHtml(rawAnswer));
const summary = count > 0 ? `Найдено ${count} ${pluralRu(count)}.` : 'По базе знаний не найдено подходящих документов.';

const nextSteps = isRefusal
  ? '\n\n<b>Что делать дальше:</b>\n• уточните вопрос конкретнее (термины, документ, дата)\n• посмотрите покрытие — /docs\n• для эскалации к HR/Legal — кнопка 🧑‍💼 ниже'
  : '';

const header = chip ? `${chip}\n\n` : '';
const sourcesHeader = isRefusal && count > 0 ? 'Ближайшие документы (вне ответа):' : 'Источники:';
const sourcesSection = count > 0 ? `\n\n${summary}\n\n${sourcesHeader}\n${sourcesBlock}` : `\n\n${summary}`;
const fullText = `${header}${answerHtml}${nextSteps}${sourcesSection}`;

const parts = splitIntoParts(fullText, TG_MAX);
const chatId = $node['Whitelist'].json.chat_id;
const replyToMessageId = $node['Whitelist'].json.user_message_id || null;
const requestLogId = $json.request_log_id || '';
const totalParts = parts.length;

const buildKeyboard = () => {
  if (!requestLogId) return null;
  const rows = [];
  const followupRow = dedupedSources.slice(0, 2).map((s) => ({
    text: `📎 ${truncate(s.section || s.file || 'подробнее', 32)}`,
    callback_data: `followup:${s._originalIdx}:${requestLogId}`,
  }));
  if (followupRow.length) rows.push(followupRow);
  rows.push([
    { text: '👍 Полезно', callback_data: `feedback:good:${requestLogId}` },
    { text: '👎 Неточно', callback_data: `feedback:bad:${requestLogId}` },
  ]);
  return { inline_keyboard: rows };
};

return parts.map((text, i) => {
  const isLast = i === totalParts - 1;
  return {
    json: {
      chat_id: chatId,
      text: totalParts > 1 ? `${text}\n\n<i>часть ${i + 1}/${totalParts}</i>` : text,
      request_log_id: requestLogId,
      is_last: isLast,
      part_index: i + 1,
      part_total: totalParts,
      inline_keyboard: isLast ? buildKeyboard() : null,
      reply_to_message_id: i === 0 ? replyToMessageId : null,
    },
  };
});

const category = $node['Whitelist'].json.category;
const chatId = $node['Whitelist'].json.chat_id;
const HUMAN_TEXT = 'Ваш запрос направлен HR/Legal на ручную обработку. Ответ придёт от профильного специалиста — сроки зависят от очереди ревью.';
const DEFAULT_TEXT = 'Оценка принята.';
const text = category === 'human' ? HUMAN_TEXT : DEFAULT_TEXT;
return [{ json: { chat_id: chatId, text } }];
